/**
 * <x-tab-panel label="Details">
 *
 * A tabpanel whose `label` is used by the parent <x-tabs> to build
 * the corresponding tab button. The label attribute is reflected
 * as a property.
 */
export class XTabPanel extends HTMLElement {
  static get observedAttributes() {
    return ['label'];
  }

  constructor() {
    super();
    // Panel content is just its light-DOM children; default styling.
    const style = document.createElement('style');
    style.textContent = `
      :host { display: block; }
      :host([hidden]) { display: none; }
    `;
    this.attachShadow({ mode: 'open' }).append(
      style,
      document.createElement('slot')
    );
  }

  get label() {
    return this.getAttribute('label') ?? '';
  }

  set label(value) {
    if (value == null) {
      this.removeAttribute('label');
    } else {
      this.setAttribute('label', String(value));
    }
  }

  attributeChangedCallback(name, oldValue, newValue) {
    if (name === 'label' && oldValue !== newValue) {
      // Allow the parent tabs container to pick up label changes.
      this.dispatchEvent(new CustomEvent('x-tab-panel:labelchange', { bubbles: true }));
    }
  }
}

if (!customElements.get('x-tab-panel')) {
  customElements.define('x-tab-panel', XTabPanel);
}

