/**
 * <x-tabs>
 *
 * Accessible tabs container. Children must be <x-tab-panel label="..."> elements.
 *
 * - Builds a `role="tablist"` (in shadow DOM) of buttons generated from the
 *   panel labels, each with `role="tab"`, `aria-selected` and `aria-controls`,
 *   wired to the panels via id / aria-labelledby.
 * - Shows exactly one panel; all others get the `hidden` attribute.
 * - Keyboard support on the tablist: ArrowLeft/ArrowRight with wrap-around,
 *   Home/End, roving tabindex, automatic activation on focus of a tab.
 * - Reflects `selected-index` attribute <-> `selectedIndex` property.
 * - Rebuilds the tablist automatically via `slotchange` when panels are
 *   added/removed; `refresh()` can also be called manually.
 */
import './x-tab-panel.js';

let uidCounter = 0;

export class XTabs extends HTMLElement {
  static get observedAttributes() {
    return ['selected-index'];
  }

  #tablist;
  #tabs = []; // [{ btn, panel }]
  #selectedIndex = 0;
  #connected = false;

  constructor() {
    super();
    const root = this.attachShadow({ mode: 'open' });
    root.innerHTML = `
      <style>
        :host { display: block; }
        [role="tablist"] { display: flex; gap: 4px; }
        [role="tab"] { cursor: pointer; }
        [role="tab"][aria-selected="true"] { font-weight: bold; }
      </style>
      <div part="tablist" role="tablist"></div>
      <slot></slot>
    `;
    this.#tablist = root.querySelector('[role="tablist"]');
    this.#tablist.addEventListener('keydown', (e) => this.#onKeydown(e));
    root.querySelector('slot').addEventListener('slotchange', () => this.refresh());
  }

  connectedCallback() {
    // Pick up any server-rendered / pre-set selected-index.
    if (this.hasAttribute('selected-index')) {
      const parsed = Number(this.getAttribute('selected-index'));
      if (Number.isInteger(parsed) && parsed >= 0) {
        this.#selectedIndex = parsed;
      }
    }
    this.#connected = true;
    this.refresh();
  }

  disconnectedCallback() {
    this.#connected = false;
  }

  attributeChangedCallback(name, oldValue, newValue) {
    if (name !== 'selected-index' || oldValue === newValue) return;
    const parsed = Number(newValue);
    if (!Number.isInteger(parsed)) return;
    const clamped = Math.max(0, Math.min(parsed, this.#tabs.length - 1));
    if (clamped === this.#selectedIndex) return;
    this.#selectedIndex = clamped;
    if (this.#connected) this.#apply();
  }

  /** Index of the currently active tab. */
  get selectedIndex() {
    return this.#selectedIndex;
  }

  set selectedIndex(value) {
    const parsed = Number(value);
    if (!Number.isInteger(parsed)) return;
    const clamped = Math.max(0, Math.min(parsed, this.#tabs.length - 1));
    this.#selectedIndex = clamped;
    // Reflection: property -> attribute. attributeChangedCallback sees no change.
    this.setAttribute('selected-index', String(clamped));
    if (this.#connected) this.#apply();
  }

  /** The currently focused/activated tab button, if any. */
  get #currentTab() {
    return this.#tabs[this.#selectedIndex]?.btn ?? null;
  }

  /**
   * Rebuild the tablist from the current <x-tab-panel> children and
   * re-apply selection state.
   */
  refresh() {
    const panels = [...this.querySelectorAll(':scope > x-tab-panel')];
    const baseId = this.id || `x-tabs-${++uidCounter}`;

    this.#tablist.textContent = '';
    this.#tabs = [];

    panels.forEach((panel, i) => {
      if (!panel.id) panel.id = `${baseId}-panel-${i}`;
      panel.setAttribute('role', 'tabpanel');

      const btn = document.createElement('button');
      btn.type = 'button';
      btn.id = `${baseId}-tab-${i}`;
      btn.setAttribute('role', 'tab');
      btn.textContent = panel.label;
      btn.setAttribute('aria-controls', panel.id);
      btn.addEventListener('click', () => this.#select(i));

      this.#tablist.appendChild(btn);
      this.#tabs.push({ btn, panel });
    });

    this.#apply();
  }

  /** Sync tab/panel ARIA state, tabindex and visibility to #selectedIndex. */
  #apply() {
    this.#tabs.forEach(({ btn, panel }, i) => {
      const selected = i === this.#selectedIndex;
      btn.tabIndex = selected ? 0 : -1;
      btn.setAttribute('aria-selected', String(selected));
      panel.setAttribute('aria-labelledby', btn.id);
      panel.toggleAttribute('hidden', !selected);
    });
  }

  /** Activate tab at index i (clamped); updates attribute + UI. */
  #select(i) {
    if (i === this.#selectedIndex) return;
    this.selectedIndex = i;
  }

  /** Roving tabindex + automatic activation keyboard handling. */
  #onKeydown(event) {
    const n = this.#tabs.length;
    if (n === 0) return;

    let next = null;
    switch (event.key) {
      case 'ArrowLeft':
        next = (this.#selectedIndex - 1 + n) % n; // wrap-around
        break;
      case 'ArrowRight':
        next = (this.#selectedIndex + 1) % n; // wrap-around
        break;
      case 'Home':
        next = 0;
        break;
      case 'End':
        next = n - 1;
        break;
      default:
        return;
    }

    event.preventDefault();
    // Automatic activation pattern: moving focus activates the tab.
    this.#select(next);
    this.#tabs[next].btn.focus();
  }
}

if (!customElements.get('x-tabs')) {
  customElements.define('x-tabs', XTabs);
}

