import { beforeEach, describe, expect, it } from 'vitest';
import '../src/x-tabs.js';

const LABELS = ['Details', 'Settings', 'Advanced'];

function makeTabs({ labels = LABELS, selectedIndex } = {}) {
  const el = document.createElement('x-tabs');
  for (const label of labels) {
    const panel = document.createElement('x-tab-panel');
    panel.setAttribute('label', label);
    el.appendChild(panel);
  }
  if (selectedIndex !== undefined) {
    el.setAttribute('selected-index', String(selectedIndex));
  }
  document.body.appendChild(el);
  return el;
}

const tabButtons = (el) => [...el.shadowRoot.querySelectorAll('[role="tab"]')];
const panels = (el) => [...el.querySelectorAll(':scope > x-tab-panel')];
const visiblePanels = (el) => panels(el).filter((p) => !p.hasAttribute('hidden'));

function pressKey(el, key, target) {
  target.dispatchEvent(
    new KeyboardEvent('keydown', { key, bubbles: true, composed: true })
  );
}

beforeEach(() => {
  document.body.textContent = '';
});

describe('<x-tabs> initial ARIA tree', () => {
  it('builds a tablist of buttons from the panel labels', () => {
    const el = makeTabs();
    const list = el.shadowRoot.querySelector('[role="tablist"]');
    expect(list).toBeTruthy();

    const tabs = tabButtons(el);
    expect(tabs.map((t) => t.textContent)).toEqual(LABELS);
    for (const tab of tabs) {
      expect(tab.tagName).toBe('BUTTON');
